  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// Matches the SportKey union already used across the frontend\n// (FavSport, Services, Heroes). Add new sports here as a one-line change.\nenum Sport {\n  football\n  cricket\n  badminton\n  chess\n  carrom\n  swimming\n  tennis\n  table_tennis\n}\n\nenum GameStatus {\n  open\n  full\n  cancelled\n  completed\n}\n\nenum BookingStatus {\n  pending\n  confirmed\n  cancelled\n}\n\n// Mirrors the authenticated person. Keyed by Clerk's userId (`clerkId`) —\n// Clerk owns identity/auth entirely; this table only holds app-specific data\n// (hearts/karma, hosted games, bookings) that Clerk has no concept of.\nmodel User {\n  id        String   @id @default(cuid())\n  clerkId   String   @unique\n  name      String\n  avatarUrl String?\n  hearts    Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  hostedGames GameSession[]     @relation(\"HostedGames\")\n  joinedGames GameParticipant[]\n  bookings    Booking[]\n  blogs       Blog[]\n}\n\nmodel Venue {\n  id          String   @id @default(cuid())\n  name        String\n  address     String\n  latitude    Float\n  longitude   Float\n  rating      Float    @default(0)\n  reviewCount Int      @default(0)\n  featured    Boolean  @default(false)\n  images      String[]\n  sports      Sport[]\n  createdAt   DateTime @default(now())\n\n  games    GameSession[]\n  bookings Booking[]\n\n  // Speeds up ORDER BY rating / featured filtering on the venues list.\n  @@index([rating])\n}\n\nmodel GameSession {\n  id        String     @id @default(cuid())\n  sport     Sport\n  format    String // e.g. \"Doubles · Regular\", \"7 A Side · Regular\"\n  level     String // e.g. \"Beginner - Professional\"\n  stateTag  String? // e.g. \"MH\"\n  startsAt  DateTime\n  endsAt    DateTime\n  capacity  Int        @default(10)\n  status    GameStatus @default(open)\n  createdAt DateTime   @default(now())\n\n  venueId String?\n  venue   Venue?  @relation(fields: [venueId], references: [id])\n\n  hostId String\n  host   User   @relation(\"HostedGames\", fields: [hostId], references: [id])\n\n  participants GameParticipant[]\n\n  @@index([status, startsAt])\n}\n\n// Join table between User and GameSession — a player can join many games,\n// a game can have many players. The host is stored separately on\n// GameSession.hostId (a host doesn't have to also be a \"participant\" row,\n// though your UI can choose to display them as one via the API response).\nmodel GameParticipant {\n  id       String      @id @default(cuid())\n  gameId   String\n  game     GameSession @relation(fields: [gameId], references: [id], onDelete: Cascade)\n  userId   String\n  user     User        @relation(fields: [userId], references: [id])\n  joinedAt DateTime    @default(now())\n\n  @@unique([gameId, userId]) // can't join the same game twice\n}\n\nmodel Booking {\n  id         String        @id @default(cuid())\n  userId     String\n  user       User          @relation(fields: [userId], references: [id])\n  venueId    String\n  venue      Venue         @relation(fields: [venueId], references: [id])\n  slotStart  DateTime\n  slotEnd    DateTime\n  status     BookingStatus @default(pending)\n  priceCents Int\n  createdAt  DateTime      @default(now())\n\n  @@index([venueId, slotStart])\n}\n\nmodel Blog {\n  id          String   @id @default(cuid())\n  title       String\n  slug        String   @unique\n  excerpt     String\n  content     String\n  category    String\n  image       String\n  readTimeMin Int      @default(3)\n  publishedAt DateTime @default(now())\n\n  authorId String\n  author   User   @relation(fields: [authorId], references: [id])\n}\n",
